// bigint type
// before bigint we can only represent numbers up to 2^53 - 1, which is 9007199254740991.
// before how we can define big numbers in JavaScript is by using the Number type,
// but it has a maximum safe integer limit of 2^53 - 1.
// provide example of big number without using bigint type
const safeInteger = Number.MAX_SAFE_INTEGER; // 9007199254740991
console.log(`Big number without BigInt: ${safeInteger}`); // 9007199254740991

// add 1 to the safe integer to show the issue with number type
console.log(`Safe integer + 1: ${safeInteger + 1}`); // 9007199254740992
console.log(`Safe integer + 20: ${safeInteger + 20}`); // 9007199254741012
// as you can see, adding 1 to the safe integer gives us 9007199254740992,
// which is correct, but adding 20 gives us 9007199254741012,
// which is incorrect because it exceeds the maximum safe integer limit.

let bigNumber: bigint = 9007199254740991n;
console.log(`Big number with BigInt: ${bigNumber}`); // 9007199254740991n

// add 1 to the big number to show that it can handle larger numbers
