// Duck Typing in TypeScript
// Duck typing is a concept in programming where the type or class of an object is
// determined by its behavior (methods and properties) rather than its explicit declaration.
// In TypeScript, this means that if an object has the necessary properties and methods,
// it can be treated as a certain type, even if it doesn't explicitly implement that type.
type Point = {
  x: number;
  y: number;
};

function printPoint(point: Point) {
  console.log(`Point coordinates: (${point.x}, ${point.y})`);
}

